169  		uint256[] memory creationFees = new uint256[](signedOps.length);
170  		if (!_hasWalletOperation(signedOps, walletIds)) {
171  			results = instantLayer.executeBatch(signedOps, signatures, fills, flexFillerSignatures);
172  			feeSelectors = _instantBatchFeeSelectors(signedOps);
173  		} else {
174  			results = new bytes[](signedOps.length);
175  			feeSelectors = new bytes4[][](signedOps.length);
176  			for (uint256 i = 0; i < signedOps.length; i++) {
177  				uint256 walletId = walletIds[i];
178  				if (_isWalletOperation(signedOps[i], walletId)) {
179  					(results[i], feeSelectors[i], creationFees[i]) = _executeWalletOperation(signedOps[i], signatures[i], walletId);
180  				} else {
181  					results[i] = _executeSingleInstantOperation(
182  						signedOps[i],
183  						signatures[i],
184  						_opValuesOrEmpty(fills, i),
185  						_opValuesOrEmpty(flexFillerSignatures, i)
186  					);
187  					feeSelectors[i] = _instantOperationFeeSelectors(signedOps[i]);
188  				}
189  			}
190  		}
191  
192  		uint256 totalFee = _collectOperationalFees(signedOps, feeSelectors, creationFees);
193  
194  		emit InstantBatchRelayed(msg.sender, signedOps.length, totalFee);
