 963  	/// @param sigCallData Signature data for verification
 964  	function _verifySignedOperation(SignedOperation calldata signedOp, bytes calldata sigCallData) private returns (bytes32) {
 965  		// Check expiry
 966  		if (signedOp.replayAttackHeader.deadline != 0 && signedOp.replayAttackHeader.deadline < block.timestamp)
 967  			revert DeadlineExpired(signedOp.replayAttackHeader.deadline);
 968  
 969  		// Validate calldata has at least selector
 970  		if (signedOp.callData.length < 4) revert CallDataLengthMismatch();
 971  
 972  		if (signedOp.target == address(this)) {
 973  			// Self-targeted operations are only valid as delegation grants
 974  			_verifyGrantOperation(signedOp);
 975  		} else if (!whitelistedTargets[signedOp.target]) {
 976  			revert TargetNotWhitelisted(signedOp.target);
 977  		}
 978  
 979  		bytes32 hash = getOperationHash(signedOp);
 980  		address signer = signedOp.signer;
 981  
 982  		if (signedOp.signerAccount.isPartyB) {
 983  			if (signer != signedOp.signerAccount.addr) revert MismatchSignerAndAccount(signer, signedOp.signerAccount.addr);
 984  			if (!isPartyBRegistered(signer)) revert UnregisteredPartyB(signer);
 985  		} else {
 986  			// Resolve the signed account now; selector authorization follows all calldata mutations.
 987  			_getAccountOwner(signedOp.signerAccount.addr);
 988  		}
 989  
 990  		// Verify signature - skip if signer is the executor (msg.sender proves identity)
 991  		// PartyA delegation is checked immediately before executing the final calldata.
 992  		if (signer != msg.sender) {
 993  			if (!SignatureChecker.isValidSignatureNow(signer, hash, sigCallData)) {
 994  				revert InvalidSignature();
 995  			}
 996  		}
 997  
 998  		// Replay protection: unified for all operations via maxUses
 999  		uint256 currentUsage = operationUsageCount[hash];
1000  		if (signedOp.maxUses > 0 && currentUsage >= signedOp.maxUses) {
1001  			revert MaxUsesExceeded(hash, signedOp.maxUses);
1002  		}
1003  		operationUsageCount[hash] = currentUsage + 1;
1004  
1005  		// Handle nonce if enabled (non-zero)
1006  		if (signedOp.replayAttackHeader.nonce != 0) {
1007  			uint256 expectedNonce = nonces[signedOp.signerAccount.addr] + 1;
1008  			if (signedOp.replayAttackHeader.nonce != expectedNonce) {
1009  				revert InvalidNonce(signedOp.signerAccount.addr, expectedNonce, signedOp.replayAttackHeader.nonce);
1010  			}
1011  			nonces[signedOp.signerAccount.addr]++;
1012  			emit NonceIncremented(signedOp.signerAccount.addr, nonces[signedOp.signerAccount.addr]);
1013  		}
1014  
1015  		return hash;
1016  	}
