176  	/// @dev Runs the original action with the original caller/value/roles. Simulation always reverts, even on success.
177  	///      Wrap failures so an inner call cannot impersonate the outer successful quote result.
178  	function execute(bytes calldata callData, bool simulation, uint256 maxTotalDebit) external returns (bytes memory result) {
179  		bytes4 selector = _checkSelector(callData);
180  		if (selector != IGaslessLayer.relayNativeGasTopUp.selector && msg.value != 0) revert IGaslessLayer.UnexpectedNativeValue(msg.value);
181  		GaslessFeeAccounting.State storage s = GaslessFeeAccounting.state();
182  		if (s.active) revert IGaslessLayer.FeeQuoteContextActive();
183  		IGaslessLayer.FeeQuote memory quote = _newQuote(IGaslessFeeConfig(address(this)));
184  		s.active = true;
185  		bool success;
186  		(success, result) = address(this).delegatecall(callData);
187  		if (!success) {
188  			if (simulation) revert IGaslessLayer.FeeQuoteExecutionFailed(result);
189  			assembly ("memory-safe") {
190  				revert(add(result, 32), mload(result))
191  			}
192  		}
193  		quote.exact = true;
194  		quote.payments = s.payments;
195  		quote.freeOpsApplied = s.freeOps;
196  		quote.nativeSponsored = s.nativeSponsored;
197  		_total(quote);
198  		if (simulation) revert IGaslessLayer.FeeQuoteResult(quote);
199  		if (quote.totalDebit18 > maxTotalDebit) revert IGaslessLayer.FeeLimitExceeded(quote.totalDebit18, maxTotalDebit);
200  		GaslessFeeAccounting.clear();
201  	}
