42  	/// @notice Sweep wallet collateral and collect deposit/creation fees in gateway proxy context.
43  	/// @dev The gateway deploys the wallet and determines its creation fee before calling this library.
44  	function sweepDepositAndCollectFee(
45  		address owner,
46  		address wallet,
47  		uint256 creationFee
48  	) external returns (uint256 netDeposit, uint256 collectedDepositFee) {
49  		IGaslessFeeConfig config = IGaslessFeeConfig(address(this));
50  		address token = config.collateralToken();
51  		uint256 grossDeposit = GaslessWallet(payable(wallet)).sweepTokenBalance(token, address(this));
52  		uint256 minimum = config.minimumDeposit();
53  		if (grossDeposit < minimum) revert IGaslessLayer.DepositAmountBelowMinimum(grossDeposit, minimum);
54  		collectedDepositFee = config.depositFee();
55  		uint256 totalFees = collectedDepositFee + creationFee;
56  		if (grossDeposit <= totalFees) revert IGaslessLayer.DepositAmountNotAboveFees(grossDeposit, totalFees);
57  		if (totalFees > 0) IERC20(token).safeTransfer(config.treasury(), totalFees);
58  		if (collectedDepositFee > 0) emit IGaslessLayer.DepositFeeCollected(owner, config.treasury(), collectedDepositFee);
59  		if (creationFee > 0) emit IGaslessLayer.WalletCreationFeeCollected(wallet, wallet, creationFee);
60  		_recordWalletPayment(token, wallet, collectedDepositFee, creationFee);
61  		netDeposit = grossDeposit - totalFees;
62  	}
